2064	
2065	impl WorkspaceIndex {
2066	    pub(crate) fn build(
2067	        root: &Utf8Path,
2068	        analyzer: &dyn LanguageAnalyzer,
2069	        enrichers: Vec<Box<dyn WorkspaceEnricher>>,
2070	        config_hash: &str,
2071	    ) -> Result<Self> {
2072	        crate::analysis::persist::init(root, config_hash)?;
2073	        // Phase 1: walk + parallel analyze
2074	        let walk_entries: Vec<Utf8PathBuf> = {
2075	            let mut entries = Vec::new();
2076	            for result in ignore::WalkBuilder::new(root).standard_filters(true).build() {
2077	                let entry = result.map_err(|e| crate::error::MonoklError::Walk {
2078	                    path: root.to_owned(),
2079	                    source: e,
2080	                })?;
2081	                if !entry.file_type().is_some_and(|t| t.is_file()) { continue; }
2082	                if let Ok(p) = Utf8PathBuf::from_path_buf(entry.into_path()) {
2083	                    if analyzer.supports(&p) { entries.push(p); }
2084	                }
2085	            }
2086	            entries
2087	        };
2088	        let mut analyses: Vec<Arc<FileAnalysis>> = walk_entries.par_iter().filter_map(|path| {
2089	            let path = path.clone();
2090	            let path_for_closure = path.clone();
2091	            match analyzer.analyze(&path, Box::new(move || {
2092	                std::fs::read_to_string(&path_for_closure)
2093	                    .map_err(|e| crate::error::MonoklError::Io(stubhub_errors::FileIoError::read(&path_for_closure, e)))
2094	            })) {
2095	                Ok(a) => Some(a),
2096	                Err(e) => { tracing::warn!("analyze failed for {path}: {e}"); None }
2097	            }
2098	        }).collect();
2099	        analyses.sort_by(|a, b| a.source_path.cmp(&b.source_path));
2100	        let mut files: Vec<Utf8PathBuf> = Vec::with_capacity(analyses.len());
2101	        let mut file_index: FxHashMap<Utf8PathBuf, FileIdx> = FxHashMap::default();
2102	        for (i, analysis) in analyses.iter().enumerate() {
2103	            let idx = FileIdx(i as u32);
2104	            files.push(analysis.source_path.clone());
2105	            file_index.insert(analysis.source_path.clone(), idx);
2106	        }
2107	        // Phase 2: stream update() through enrichers
2108	        let mut enrichers = enrichers;
2109	        for analysis in &analyses {
2110	            if let Some(&idx) = file_index.get(&analysis.source_path) {
2111	                for enricher in &mut enrichers {
2112	                    enricher.update(idx, analysis);
2113	                }
2114	            }
2115	        }
2116	        // Phase 3: finalize enrichers
2117	        let mut index = WorkspaceIndex {
2118	            files, file_index,
2119	            import_graph: ImportGraph::new(),
2120	            symbol_index: SymbolIndex::new(),
2121	        };
2122	        for enricher in enrichers { enricher.finalize(&mut index); }
2123	        crate::analysis::persist::flush(root, config_hash)?;
2124	        Ok(index)
2125	    }
