6196	### PR semantics
6197	
6198	```rust
6199	fn effective_pr_range(repo: &gix::Repository, scope: &QueryScopeOptions) -> Result<(String, String)> {
6200	    let (base, head) = requested_git_range(scope);
6201	    let base_id = resolve_commit_id(repo, base)?;
6202	    let head_id = resolve_commit_id(repo, head)?;
6203	    let merge_base = repo
6204	        .merge_base(base_id.detach(), head_id.detach())
6205	        .map_err(|err| MonoklError::Git { operation: "merge-base", message: format!("{base} {head}: {err}") })?;
6206	
6207	    Ok((merge_base.to_string(), head.to_owned()))
6208	}
6209	
6210	pub(crate) fn build_pr_change_set(root: &Utf8Path, scope: &QueryScopeOptions) -> Result<ChangeSet> {
6211	    let (base, head) = requested_git_range(scope);
6212	    build_change_set(
6213	        root,
6214	        base,
6215	        head,
6216	        ChangeSetMode::PrAware,
6217	        scope.mode == crate::types::QueryScope::ChangedLines,
6218	    )
6219	}
6220	```
6221	
6222	`requested_git_range` defaults `base` to `"origin/main"` and `head` to `"HEAD"`. `ChangeSetMode::Snapshot` (used only by `diff`) keeps the literal base/head pair without applying merge-base substitution; `ChangeSetMode::PrAware` replaces base with `merge-base(base, head)`. This is the load-bearing distinction the 0.6.0 changelog calls out — `diff` stays explicit-snapshot.
