6375	
6376	```rust
6377	//! Shared JSON field projection.
6378	//!
6379	//! CLI and MCP surfaces both need compact, question-shaped output. Projection
6380	//! lives in the library so those surfaces can share one contract.
6381	
6382	use serde_json::Value;
6383	
6384	use crate::error::Result;
6385	use crate::types::{InspectResult, SearchResponse};
6386	
6387	#[must_use]
6388	pub fn project_fields(value: Value, fields: &[String]) -> Value {
6389	    let fields: Vec<&str> = fields.iter().map(String::as_str).map(str::trim)
6390	        .filter(|field| !field.is_empty()).collect();
