6394	
6395	pub fn project_inspect_result(result: &InspectResult, fields: &[String]) -> Result<Value> {
6396	    let value = serde_json::to_value(result)?;
6397	    if fields.iter().all(|field| field.trim().is_empty()) {
6398	        return Ok(value);
6399	    }
6400	    Ok(project_fields(value, &inspect_projection_fields(fields)))
6401	}
6402	
6403	pub fn project_search_response(result: &SearchResponse, fields: &[String]) -> Result<Value> {
6404	    let value = serde_json::to_value(result)?;
6405	    if fields.iter().all(|field| field.trim().is_empty()) {
