6407	    }
6408	    Ok(project_fields(value, &search_projection_fields(fields)))
6409	}
6410	
6411	#[must_use]
6412	pub fn prune_empty(value: Value) -> Value {
6413	    match value {
6414	        Value::Object(map) => {
6415	            let mut pruned = serde_json::Map::new();
6416	            for (key, child) in map {
6417	                let child = prune_empty(child);
6418	                if !is_minimal_empty(&child) {
6419	                    pruned.insert(key, child);
6420	                }
6421	            }
6422	            Value::Object(pruned)
6423	        }
6424	        Value::Array(items) => {
6425	            let items = items.into_iter().map(prune_empty)
6426	                .filter(|item| !is_minimal_empty(item)).collect();
6427	            Value::Array(items)
6428	        }
6429	        other => other,
6430	    }
6431	}
6432	
6433	fn project_value(value: Value, fields: &[&str]) -> Value {
6434	    match value {
6435	        Value::Object(map) => {
6436	            let mut projected = serde_json::Map::new();
6437	            for (key, child) in map {
6438	                if fields.iter().any(|field| *field == key) {
6439	                    projected.insert(key, child);
6440	                    continue;
6441	                }
6442	                let prefix = format!("{key}.");
6443	                let child_fields: Vec<&str> = fields.iter()
6444	                    .filter_map(|field| field.strip_prefix(&prefix)).collect();
6445	                if !child_fields.is_empty() {
6446	                    let child = project_value(child, &child_fields);
6447	                    if !is_empty_projection(&child) {
6448	                        projected.insert(key, child);
6449	                    }
6450	                }
6451	            }
6452	            Value::Object(projected)
6453	        }
6454	        Value::Array(items) => Value::Array(items.into_iter()
6455	            .map(|item| project_value(item, fields)).collect()),
6456	        other => other,
6457	    }
6458	}
6459	
6460	fn search_projection_fields(fields: &[String]) -> Vec<String> {
6461	    let mut projected = Vec::new();
6462	    let mut has_result_field = false;
6463	    for field in fields.iter().map(String::as_str).map(str::trim) {
6464	        if field.is_empty() { continue; }
6465	        let field = match field {
6466	            "snippet" => "code",
6467	            "score" => "finalScore",
6468	            other => other,
6469	        };
6470	        match field {
6471	            "results" | "totalBlocksBeforeTruncation" | "truncated"
6472	            | "truncationMarker" | "totalBytes" | "totalTokens"
6473	            | "diagnostics" => projected.push(field.to_owned()),
6474	            _ if field.starts_with("results.") => {
6475	                has_result_field = true;
6476	                projected.push(field.to_owned());
6477	            }
6478	            _ => {
6479	                has_result_field = true;
6480	                projected.push(format!("results.{field}"));
6481	            }
6482	        }
6483	    }
6484	    if has_result_field {
6485	        projected.push("truncated".to_owned());
6486	        projected.push("totalTokens".to_owned());
6487	        projected.push("diagnostics".to_owned());
6488	    }
6489	    projected.sort();
6490	    projected.dedup();
6491	    projected
6492	}
6493	
6494	fn inspect_projection_fields(fields: &[String]) -> Vec<String> {
6495	    let mut projected = Vec::new();
6496	    let mut has_entry_field = false;
6497	    let mut has_entry_file = false;
6498	    for field in fields.iter().map(String::as_str).map(str::trim) {
6499	        if field.is_empty() { continue; }
6500	        match field {
6501	            "entries" | "fileCount" | "diagnostics" => projected.push(field.to_owned()),
6502	            _ if field.starts_with("entries.") => {
6503	                if field == "entries.file" { has_entry_file = true; }
6504	                has_entry_field = true;
6505	                projected.push(field.to_owned());
6506	            }
6507	            _ => {
6508	                if field == "file" { has_entry_file = true; }
6509	                has_entry_field = true;
6510	                projected.push(format!("entries.{field}"));
6511	            }
6512	        }
6513	    }
6514	    if has_entry_field {
6515	        if !has_entry_file { projected.push("entries.file".to_owned()); }
6516	        projected.push("fileCount".to_owned());
6517	        projected.push("diagnostics".to_owned());
6518	    }
6519	    projected.sort();
6520	    projected.dedup();
6521	    projected
6522	}
6523	
6524	fn is_empty_projection(value: &Value) -> bool {
6525	    match value {
6526	        Value::Object(map) => map.is_empty(),
6527	        Value::Array(items) => !items.is_empty() && items.iter().all(is_empty_projection),
6528	        _ => false,
6529	    }
6530	}
6531	
6532	fn is_minimal_empty(value: &Value) -> bool {
6533	    match value {
6534	        Value::Null | Value::Bool(false) => true,
6535	        Value::Bool(true) => false,
6536	        Value::Number(n) => n.as_i64() == Some(0) || n.as_u64() == Some(0) || n.as_f64() == Some(0.0),
6537	        Value::String(s) => s.is_empty(),
6538	        Value::Array(items) => items.is_empty(),
6539	        Value::Object(map) => map.is_empty(),
6540	    }
6541	}
6542	```
6543	
6544	Behaviors:
6545	
6546	- `project_fields` walks the JSON tree retaining only keys that match the explicit field list or have a child match via dot-notation prefix.
6547	- `project_search_response` aliases `snippet`→`code` and `score`→`finalScore`, auto-wraps unrecognized fields under `results.`, and unconditionally surfaces `truncated`/`totalTokens`/`diagnostics` so projected output still carries truncation context.
6548	- `project_inspect_result` auto-wraps fields under `entries.`, force-includes `entries.file` so projected entries retain identity, and surfaces `fileCount`/`diagnostics`.
6549	- `prune_empty` is the backbone of `--format minimal`: it recursively drops `null`, `false`, `0`/`0.0`, empty strings, empty arrays, and empty objects.
