6643	pub(crate) fn require_precision_capability(
6644	    warned_languages: &mut BTreeSet<LanguageId>,
6645	    analyzer: &dyn LanguageAnalyzer,
6646	    path: &Utf8Path,
6647	    diagnostics: &mut Vec<Diagnostic>,
6648	    precision: CapabilityPrecision,
6649	    requirement: PrecisionRequirement,
6650	) -> bool {
6651	    if precision < requirement.minimum {
6652	        if warned_languages.insert(analyzer.language_id()) {
6653	            diagnostics.push(Diagnostic {
6654	                kind: DiagnosticKind::Skipped,
6655	                path: Some(path.to_owned()),
