6713	fn follow_rust_canonical_source(
6714	    analyzer: &dyn LanguageAnalyzer,
6715	    start: &Utf8Path,
6716	    symbol: &str,
6717	    diagnostics: &mut Vec<Diagnostic>,
6718	) -> Utf8PathBuf {
6719	    let mut current = start.to_owned();
6720	    let mut visited = std::collections::BTreeSet::from([current.clone()]);
6721	
6722	    for _ in 0..10 {
6723	        let analysis = match analyze_with_profile(analyzer, &current, AnalysisProfile::Structural) {
6724	            Ok(analysis) => analysis,
6725	            Err(e) => { /* push Degraded, return current */ return current; }
6726	        };
6727	
6728	        let has_declaration = analysis.symbols.iter().any(|entry| {
6729	            entry.name == symbol
6730	                && analysis.exports.iter()
6731	                    .any(|export| export.name == symbol && !export.re_export)
6732	        });
6733	        if has_declaration { return current; }
6734	
6735	        let Some(re_export_line) = analysis.exports.iter()
6736	            .find(|export| export.name == symbol && export.re_export)
6737	            .map(|export| export.line)
6738	        else { return current; };
6739	
6740	        let next = analysis.dependencies.iter().find_map(|dep| {
6741	            (dep.line == re_export_line
6742	                && dep.bindings.iter().any(|binding| binding_matches_symbol(binding, symbol)))
6743	            .then(|| dependency_target_resolved(&dep.target).map(Utf8Path::to_owned))
6744	            .flatten()
6745	        });
6746	
6747	        let Some(next) = next else { return current; };
6748	        if !visited.insert(next.clone()) { return current; }
6749	        current = next;
6750	    }
6751	    current
6752	}
