6822	fn expand_paths_inner<F>(paths: &[Utf8PathBuf], opts: &SourceScanOptions, supports: F) -> Result<Vec<Utf8PathBuf>>
6823	where F: Fn(&Utf8Path) -> bool {
6824	    use ignore::WalkBuilder;
6825	    let scan_paths: Vec<Utf8PathBuf> = if paths.is_empty() { vec![Utf8PathBuf::from(".")] } else { paths.to_vec() };
6826	    let mut files = Vec::new();
6827	
6828	    for path in scan_paths {
6829	        if path.is_dir() {
6830	            let walk = WalkBuilder::new(path.as_std_path())
6831	                .standard_filters(!opts.no_gitignore).build();
6832	            for entry in walk {
6833	                let entry = entry.map_err(|source| MonoklError::Walk { path: path.clone(), source })?;
6834	                if !entry.file_type().is_some_and(|t| t.is_file()) { continue; }
6835	                let Ok(file) = Utf8PathBuf::from_path_buf(entry.into_path()) else { continue; };
6836	                if !opts.allow_tests && is_test_path(&file) { continue; }
6837	                if supports(&file) { files.push(file); }
6838	            }
6839	        } else {
6840	            if !opts.allow_tests && is_test_path(&path) { continue; }
6841	            if supports(&path) { files.push(path); }
6842	        }
6843	    }
6844	    files.sort();
6845	    files.dedup();
6846	    Ok(files)
6847	}
