6889	## 13. `io_safety.rs`
6890	
6891	User-facing read safety: 50 MB size cap, symlink rejection.
6892	
6893	```rust
6894	//! File I/O safety helpers.
6895	//!
6896	//! Bounds input sizes before reading to avoid allocator bombs when the caller
6897	//! hands us `/dev/zero`, a checked-in multi-gigabyte minified bundle, or a
6898	//! similar surprise. Also rejects symlinks at read time so a hostile fixture
6899	//! (`src/data.ts` → `/etc/passwd`) can't exfiltrate via `mnkl extract`.
6900	
6901	use camino::Utf8Path;
6902	use stubhub_errors::FileIoError;
6903	
6904	use crate::error::{MonoklError, Result};
6905	
6906	pub const MAX_INSPECTABLE_FILE_SIZE: u64 = 50 * 1024 * 1024;
6907	
6908	pub fn read_to_string_capped(path: &Utf8Path) -> Result<String> {
6909	    let meta = std::fs::symlink_metadata(path.as_std_path())
6910	        .map_err(|e| MonoklError::Io(FileIoError::read(path, e)))?;
6911	
6912	    if meta.file_type().is_symlink() {
6913	        return Err(MonoklError::SymlinkRejected { path: path.to_owned() });
6914	    }
6915	
6916	    if meta.len() > MAX_INSPECTABLE_FILE_SIZE {
6917	        return Err(MonoklError::FileTooLarge {
6918	            path: path.to_owned(),
6919	            size: meta.len(),
6920	            cap: MAX_INSPECTABLE_FILE_SIZE,
6921	        });
6922	    }
6923	
6924	    // nosemgrep: rust.actix.path-traversal.tainted-path.tainted-path
6925	    std::fs::read_to_string(path.as_std_path())
6926	        .map_err(|e| MonoklError::Io(FileIoError::read(path, e)))
6927	}
6928	```
6929	
6930	Used at user-facing entry points (search, inspect, extract, refs, definition). Internal cache-loading paths trust their inputs and stay on plain `fs::read_to_string`. Pipeline-level root containment (`PathOutsideRoot`) is enforced separately for commands like `dependents`.
